# -*- coding: utf-8 -*-
# Сверка с ответами учебника Мерзляк 10, часть 2 (расхождения 70–109): пересчитано вручную + SymPy (check_mz2.py), условия сверены со сканом.
KB = "ключ неверен (сверка с ответом учебника Мерзляк 10 и пересчёт вручную): "
SRC = "сверка с ответами учебника Мерзляк 10 (углублённый) 25.09 + пересчёт вручную"
P = {}
def K(t, k, note, **kw):
    P[t] = {"k": k, "why": KB + note, "src": SRC}; P[t].update(kw)
OLD = lambda v, n: [(v, "прежний (неверный) ключ: " + n)]
K("G10_TB_§39_39_19_2", r"возрастает на $\left(-\dfrac{\pi}{8}+\pi k;\ \dfrac{\pi}{8}+\pi k\right)$, убывает на $\left(\dfrac{\pi}{8}+\pi k;\ \dfrac{7\pi}{8}+\pi k\right)$, $x=\dfrac{\pi}{8}+\pi k$ — точки максимума, $x=-\dfrac{\pi}{8}+\pi k$ — точки минимума, $k \in \mathbb{Z}$",
  "f′ = 2cos 2x − √2 > 0 ⇔ cos 2x > √2/2 ⇔ x ∈ (−π/8 + πk; π/8 + πk) (было (−3π/8; π/8), минимум 5π/8)")
K("G10_TB_§35_35_22_4", r"$\dfrac{\pi}{2} + \pi n$, $n \in \mathbb{Z}$", "sin′x = cos x = 0 ⇔ x = π/2 + πn (было πn)", dadd=OLD(r"$\pi n, n \in \mathbb{Z}$", "решено sin x = 0 вместо cos x = 0"))
K("G10_TB_§39_39_7_6", r"$x_{\max} = -\dfrac{1}{4}$; $x_{\max} = 1$; $x_{\min} = 0$", "f′ = −2x(4x + 1)(x − 1): знаки +, −, +, − ⇒ максимумы −1/4 и 1, минимум 0 (был пропущен x_max = −1/4)")
K("G10_TB_§40_40_9_1", r"Наибольшее: $\dfrac{3}{2}$, наименьшее: $1$", "s = sin 2x ∈ [0; 1], f = −2s² + 2s + 1: наибольшее 3/2 при s = 1/2, наименьшее 1 при s = 0 и s = 1 (было 0)")
K("G10_TB_§40_40_3_3", r"$0, 100$", "f = ((x + 1)(x − 2))², (x + 1)(x − 2) на [−2; 4] от −9/4 до 10: наименьшее 0, наибольшее 100 (было 0, 81)", dadd=OLD(r"$0, 81$", "неверное наибольшее"))
K("G10_TB_§39_39_23_2", r"возрастает на $(0; \dfrac{2}{5})$ и $(2; +\infty)$, убывает на $(\dfrac{2}{5}; 2)$, $x = \dfrac{2}{5}$ — точка максимума, $x = 2$ — точка минимума",
  "f′ = (x − 2)(5x − 2)/(2√x): максимум 2/5, минимум 2 (было: 2/5 — минимум, точка 2 пропущена)")
K("G10_TB_§30_30_5_13", r"$x = \dfrac{\pi}{3} + \pi k$; $x = -\dfrac{\pi}{3} + \pi k$", "c = cos²x: 4c² − 9c + 2 = 0, c = 1/4 (c = 2 невозможно) ⇒ x = ±π/3 + πk; ±π/4 + πk не корни: 2 + 2 ≠ 7 (было с ними)")
K("G10_TB_§42_42_55", r"$x = \dfrac{3\pi}{4}$; $x = 2\pi - \operatorname{arctg}\dfrac{1}{3}$", "sin x ≥ 0: tg x = −1 ⇒ 3π/4; sin x < 0: tg x = −1/3 ⇒ 2π − arctg(1/3); 7π/4 не корень: √2/2 ≠ −√2/2 (было 3π/4; 7π/4)")
K("G10_TB_§39_39_14_6", r"возрастает на $(3; +\infty)$, убывает на $(-\infty; 3)$, точек экстремума нет", "f′ = 2/(x − 3)³ > 0 при x > 3 (промежутки были переставлены)")
K("G10_TB_§40_40_2_2", r"Наибольшее значение: $1$, наименьшее значение: $-2$", "f′ = −(3x − 1)(x + 1); f(−2) = 1, f(−1) = −2, f(0) = −1 (было −1 и −5)")
